# deploy_neural_service.ps1 — Instala Neural Engine Service no Ururau
$base = "C:\Users\fabri\Downloads\PURAL_EDITORIAL_V47_12_PREMIUM_OPERACIONAL\PURAL_EDITORIAL_V47_12_PREMIUM_OPERACIONAL"

function Decode-AndWrite {
    param($b64, $path)
    $bytes = [System.Convert]::FromBase64String($b64)
    $fullPath = Join-Path $base $path
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "[OK] $path ($($bytes.Length) bytes)" -ForegroundColor Green
}

Write-Host "=== DEPLOY NEURAL SERVICE ===" -ForegroundColor Cyan

Decode-AndWrite "" "sistema\neural_service.py"
Decode-AndWrite "" "sistema\neural_hooks.py"
Decode-AndWrite "" "49_INICIAR_NEURAL.bat"

Write-Host "" 
Write-Host "CONCLUIDO. Proximos passos:" -ForegroundColor Cyan
Write-Host "  1. Edite sistema\ururau_painel.py para adicionar o botao Neural" -ForegroundColor Yellow
Write-Host "  2. Edite sistema\ururau_monitor.py para chamar neural_hooks nos ciclos" -ForegroundColor Yellow
Write-Host "  3. Rode: .\49_INICIAR_NEURAL.bat" -ForegroundColor Yellow
Write-Host "  4. Ou inicie pelo painel GUI" -ForegroundColor Yellow
